Kirish tayyorlash.kod:
var p=$json.paket||$json;
return{json:{
  job_id:p.job_id||"UNKNOWN",
  mavzu_kod:p.mavzu_kod||"T1",
  burchak:(p.burchaklar&&p.burchaklar.tg_post&&p.burchaklar.tg_post[0])||"Haftanin rakami",
  faktlar:p.faktlar||[],
  sarlavha:p.sarlavha||"",
  urinish:1
}};

Post parse.kod:
var raw=$json.content&&$json.content[0]&&$json.content[0].text||JSON.stringify($json);
var parsed;
try{var s=raw.indexOf("{");var e=raw.lastIndexOf("}");parsed=JSON.parse(raw.slice(s,e+1));}
catch(err){return{json:{xato:true,tur:"PARSE_FAIL",xabar:String(err),urinish:$("Kirish tayyorlash").item.json.urinish||1}};}
var faktlar=$("Kirish tayyorlash").item.json.faktlar||[];
var belgi=parseInt(parsed.belgi_soni||0);
var postHtml=parsed.post_html||"";
return{json:{post_html:postHtml,belgi_soni:belgi,faktlar:faktlar,burchak:$("Kirish tayyorlash").item.json.burchak,job_id:$("Kirish tayyorlash").item.json.job_id,urinish:$("Kirish tayyorlash").item.json.urinish||1}};

Post tekshiruvi.kod:
var postHtml=$json.post_html||"";
var faktlar=$json.faktlar||[];
var xatolar=[];
// Strip HTML tags to count chars
var bare=postHtml.replace(new RegExp("<[^>]+>","g"),"").replace(new RegExp("&[a-z]+;","g"),"X");
var uzunlik=bare.length;
if(uzunlik<500)xatolar.push("Uzunlik "+uzunlik+" belgi, min 500");
if(uzunlik>900)xatolar.push("Uzunlik "+uzunlik+" belgi, max 900");
// Check only <b> and <i> tags
var badTags=postHtml.match(new RegExp("<(?!\/?(b|i))[^>]+>","gi"))||[];
if(badTags.length>0)xatolar.push("Noto'g'ri teglar: "+badTags.join(", "));
// Check Kaynak
if(postHtml.indexOf("Kaynak:")<0&&postHtml.indexOf("kaynak:")<0)xatolar.push("Kaynak: qatori yo'q");
// Check numbers from faktlar
var faktRaqamlar=[];
for(var fi=0;fi<faktlar.length;fi++){
  var m=String(faktlar[fi].matn||"").match(new RegExp("[0-9]+","g"))||[];
  for(var j=0;j<m.length;j++)faktRaqamlar.push(m[j]);
}
var pctM=bare.match(new RegExp("%([0-9]+)","g"))||[];
for(var pi=0;pi<pctM.length;pi++){
  var num=pctM[pi].replace("%","");
  var found=false;
  for(var fk=0;fk<faktRaqamlar.length;fk++){if(faktRaqamlar[fk].indexOf(num)>=0){found=true;break;}}
  if(!found)xatolar.push("Ixtiro raqam: "+pctM[pi]+" faktlarda yoq");
}
return{json:{holat:xatolar.length===0?"PASS":"FAIL",xatolar:xatolar,post_html:postHtml,belgi_soni:uzunlik,job_id:$json.job_id,burchak:$json.burchak,urinish:$json.urinish||1}};
